DIRS = 'NESW'
STEP = {'N': (0, 1), 'E': (1, 0), 'S': (0, -1), 'W': (-1, 0)}

def solution(spec, obstacles):
    lines = [ln.strip() for ln in spec.strip().split('\n') if ln.strip()]
    max_x, max_y = map(int, lines[0].split())
    rovers = []
    for i in range(1, len(lines), 2):
        x, y, d = lines[i].split()
        cmds = lines[i + 1] if i + 1 < len(lines) else ''
        rovers.append([int(x), int(y), d, cmds])
    blocked = {tuple(o) for o in obstacles}
    # every rover is on the plateau from the start, so all start cells are taken
    taken = {(r[0], r[1]) for r in rovers}
    out = []
    for r in rovers:
        x, y, d, cmds = r
        taken.discard((x, y))                 # this rover is the one moving
        stopped = False
        for c in cmds:
            if c == 'L':
                d = DIRS[(DIRS.index(d) - 1) % 4]
            elif c == 'R':
                d = DIRS[(DIRS.index(d) + 1) % 4]
            elif c == 'M':
                dx, dy = STEP[d]
                nx, ny = x + dx, y + dy
                if not (0 <= nx <= max_x and 0 <= ny <= max_y) or (nx, ny) in blocked or (nx, ny) in taken:
                    stopped = True
                    break
                x, y = nx, ny
        taken.add((x, y))
        out.append(f'{x} {y} {d}' + (' STOPPED' if stopped else ''))
    return '\n'.join(out)
